import type { Page } from "@playwright/test";
import { PageObject } from "pomwright";

// generated by following skills/pomwright-map-site on http://localhost:9000/testfilters, from its snapshot
export type Paths =
	| "region@accessible"
	| "region@accessible.heading"
	| "region@accessible.button@red"
	| "region@accessible.button@resetColor"
	| "region@accessible.buttons"
	| "section@primaryColors"
	| "section@primaryColors.heading"
	| "section@primaryColors.button@red";

export class TestFiltersPage extends PageObject<Paths> {
	constructor(page: Page) {
		super(page, "http://localhost:9000", "/testfilters");
	}

	protected defineLocators(): void {
		this.add("region@accessible").getByRole("region", { name: "Accessible Section" });
		this.add("region@accessible.heading").getByRole("heading", { level: 2 });
		this.add("region@accessible.button@red").getByRole("button", { name: "Red" });
		this.add("region@accessible.button@resetColor").getByRole("button", { name: "Reset Color" });
		this.add("region@accessible.buttons").getByRole("button");
		// a generic container: the suggestion named it by its id, section1
		this.add("section@primaryColors").getById("section1");
		this.add("section@primaryColors.heading").getByRole("heading", { name: "Primary Colors Section" });
		this.add("section@primaryColors.button@red").getByRole("button", { name: "Red" });
	}
}
